// Product registry — one directory per product under server/content/products/.
//
//   server/content/products/<product_id>/product.json
//
// Manifest fields:
//   product_id   must equal the directory name
//   type         "single" (owns a content file) | "bundle" (includes other products)
//   content_file relative path to the full quiz JSON (single only)
//   theme_ids    ids this product unlocks, or "*" for every theme in the file
//   includes     product_id list (bundle only)
//
// Adding a test = dropping in a new product directory. The server, store schema
// and admin tooling never need to change. The legacy full quiz file stays where
// it is (server/content/quiz_content_upgrade.json) and backs greek_goddess, so
// the live product's questions, scoring, UI and results are byte-identical.
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const PRODUCTS_DIR = join(HERE, "content", "products");

// The product the current site has been selling since the paywall shipped.
// Old license rows and parameter-less API calls resolve to it (requirement:
// existing codes must keep working with no migration action).
export const DEFAULT_PRODUCT_ID = "greek_goddess";

const registry = new Map(); // product_id -> { manifest, dir }
const contentCache = new Map(); // absolute file path -> parsed JSON

function loadContent(file) {
  const abs = resolve(file);
  if (!contentCache.has(abs)) contentCache.set(abs, JSON.parse(readFileSync(abs, "utf8")));
  return contentCache.get(abs);
}

for (const entry of readdirSync(PRODUCTS_DIR, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const manifestPath = join(PRODUCTS_DIR, entry.name, "product.json");
  if (!existsSync(manifestPath)) continue;
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  if (manifest.product_id !== entry.name) {
    throw new Error(`product manifest mismatch: ${manifestPath} declares ${manifest.product_id}`);
  }
  registry.set(manifest.product_id, { manifest, dir: join(PRODUCTS_DIR, entry.name) });
}

export function listProducts() {
  return [...registry.values()].map(({ manifest }) => manifest);
}
