  const types = Array.isArray(t) ? t : [t];
  const ok = types.some((tt) => matchType(tt, value));
  if (!ok) { errs.push(`${path}: 期望类型 ${types.join("|")}，实际 ${describe(value)}`); return; }
  if (schema.enum && !schema.enum.includes(value)) errs.push(`${path}: 必须是 ${schema.enum.join(" / ")}，实际 ${JSON.stringify(value)}`);
  if (typeof value === "string") {
    if (schema.minLength != null && value.length < schema.minLength) errs.push(...);
    if (schema.maxLength != null && value.length > schema.maxLength) errs.push(...);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errs.push(`${path}: 不匹配 ${schema.pattern}`);
  }
  if (typeof value === "number") {
    if (schema.minimum != null && value < schema.minimum) ...
    if (schema.maximum != null && value > schema.maximum) ...
  }
  if (Array.isArray(value)) {
    if (schema.minItems != null && value.length < ...) ...
    if (schema.maxItems != null && ...) ...
    if (schema.items) value.forEach((v, i) => validateNode(schema.items, v, `${path}[${i}]`, errs));
  }
  if (value && typeof value === "object" && !Array.isArray(value)) {
    for (const req of schema.required ?? []) if (!(req in value)) errs.push(`${path}: 缺少必填字段 "${req}"`);
    for (const [k, v] of Object.entries(value)) {
      const ps = schema.properties?.[k];
      if (ps) validateNode(ps, v, `${path}.${k}`, errs);
      else if (schema.additionalProperties === false) errs.push(`${path}: 未知字段 "${k}"`);
    }
  }
}
function matchType(tt, v) {
  switch (tt) {
    case "string": return typeof v === "string";
    case "integer": return Number.isInteger(v);
    case "number": return typeof v === "number" && Number.isFinite(v);
    case "boolean": return typeof v === "boolean";
    case "array": return Array.isArray(v);
    case "object": return v && typeof v === "object" && !Array.isArray(v);
    case "null": return v === null;
    default: return false;
  }
}
