#!/usr/bin/env node
// create-test.mjs — Test Factory 开工命令。
//
// 用法：
//   node factory/create-test.mjs <brief.json>
//   node factory/create-test.mjs factory/examples/example-brief.json
//
// 职责（有意保持最小）：
//   1. 按 factory/brief.schema.json 校验 brief（内置 draft-07 子集校验器，零依赖）
//   2. 附加语义校验：product_id 唯一性 / 防覆盖 / custom-lite profile 硬约束
//   3. 创建标准工作目录 factory/work/<product_id>/，写入各阶段任务文件骨架
//   4. 打印下一步操作说明，交给后续 agent 按固定协议继续生产
//
// 不调用模型 API，不生成任何内容；未完成处一律写 TODO / null，不假造结果。

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const FACTORY = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(FACTORY, "..");
const WORK_DIR = join(FACTORY, "work");
const PRODUCTS_DIR = join(REPO, "server", "content", "products");

const FAIL = (msg) => {
  console.error(`✗ ${msg}`);
  process.exit(1);
};
const TODO = "TODO（未完成，禁止假造；完成后删除此标记并填写依据）";

/* ---------------------------------------------------------------- validator */
// 支持 draft-07 子集：type(含数组)/required/properties/additionalProperties/
// enum/pattern/minLength/maxLength/minimum/maximum/items/minItems/maxItems
function matchType(t, v) {
  switch (t) {
    case "string": return typeof v === "string";
    case "integer": return Number.isInteger(v);
    case "number": return typeof v === "number" && Number.isFinite(v);
    case "boolean": return typeof v === "boolean";
    case "array": return Array.isArray(v);
    case "object": return v !== null && typeof v === "object" && !Array.isArray(v);
    case "null": return v === null;
    default: return false;
  }
}
function describe(v) {
  if (v === null) return "null";
  if (Array.isArray(v)) return "array";
  return typeof v;
}
function validateNode(schema, value, path, errs) {
  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
  if (types.length && !types.some((t) => matchType(t, value))) {
    errs.push(`${path}: 期望类型 ${types.join("|")}，实际 ${describe(value)}`);
    return;
  }
  if (schema.enum && !schema.enum.includes(value)) {
    errs.push(`${path}: 必须是 ${schema.enum.join(" / ")}，实际 ${JSON.stringify(value)}`);
  }
  if (typeof value === "string") {
    if (schema.minLength != null && value.length < schema.minLength)
      errs.push(`${path}: 长度 ${value.length} < minLength ${schema.minLength}`);
    if (schema.maxLength != null && value.length > schema.maxLength)
      errs.push(`${path}: 长度 ${value.length} > maxLength ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value))
      errs.push(`${path}: "${value}" 不匹配 /${schema.pattern}/`);
  }
  if (typeof value === "number") {
    if (schema.minimum != null && value < schema.minimum)
      errs.push(`${path}: ${value} < minimum ${schema.minimum}`);
    if (schema.maximum != null && value > schema.maximum)
      errs.push(`${path}: ${value} > maximum ${schema.maximum}`);
  }
  if (Array.isArray(value)) {
    if (schema.minItems != null && value.length < schema.minItems)
      errs.push(`${path}: ${value.length} 项 < minItems ${schema.minItems}`);
    if (schema.maxItems != null && value.length > schema.maxItems)
      errs.push(`${path}: ${value.length} 项 > maxItems ${schema.maxItems}`);
    if (schema.items) value.forEach((v, i) => validateNode(schema.items, v, `${path}[${i}]`, errs));
  }
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    for (const req of schema.required ?? []) {
      if (!(req in value)) errs.push(`${path}: 缺少必填字段 "${req}"`);
    }
    for (const [k, v] of Object.entries(value)) {
      const ps = schema.properties?.[k];
      if (ps) validateNode(ps, v, `${path}.${k}`, errs);
      else if (schema.additionalProperties === false)
        errs.push(`${path}: 未知字段 "${k}"（schema additionalProperties=false）`);
    }
  }
}
const validateBrief = (schema, brief) => {
  const errs = [];
  validateNode(schema, brief, "brief", errs);
  return errs;
};

/* ------------------------------------------------------------- load & check */
const [briefArg] = process.argv.slice(2);
if (!briefArg) {
  console.log("用法: node factory/create-test.mjs <brief.json>");
  console.log("示例: node factory/create-test.mjs factory/examples/example-brief.json");
  process.exit(1);
}
const briefPath = resolve(briefArg);
if (!existsSync(briefPath)) FAIL(`brief 文件不存在: ${briefPath}`);

let brief;
try {
  brief = JSON.parse(readFileSync(briefPath, "utf8"));
} catch (e) {
  FAIL(`brief 不是合法 JSON: ${e.message}`);
}
const schema = JSON.parse(readFileSync(join(FACTORY, "brief.schema.json"), "utf8"));
const errors = validateBrief(schema, brief);
if (errors.length) {
  console.error(`✗ brief 未通过 schema 校验（${errors.length} 项）：`);
  for (const e of errors) console.error(`  - ${e}`);
  process.exit(1);
}

const { product_id, commercial_mode } = brief;
const warnings = [];

// 1) product_id 不得与在售产品目录冲突（绝不覆盖已有产品）
const RESERVED = new Set(["work", "examples", "profiles", "skills", "creators", "templates"]);
if (RESERVED.has(product_id)) FAIL(`product_id "${product_id}" 是工厂保留名，请更换。`);
if (existsSync(PRODUCTS_DIR)) {
  const clash = readdirSync(PRODUCTS_DIR).find(
    (d) => d.toLowerCase() === product_id.toLowerCase()
  );
  if (clash) FAIL(`product_id "${product_id}" 与在售产品目录 server/content/products/${clash} 冲突。不允许覆盖已有产品，请更换 ID。`);
}

// 2) 防覆盖：工作目录已存在则拒绝
const workDir = join(WORK_DIR, product_id);
if (existsSync(workDir)) {
  FAIL(`工作目录已存在: factory/work/${product_id}（防覆盖，不重跑。如需重开请手动归档旧目录后改名）`);
}

// 3) custom-lite profile：custom_private 模式下硬约束
const profilePath = join(FACTORY, "profiles", "custom-lite.json");
const profile = commercial_mode === "custom_private" && existsSync(profilePath)
  ? JSON.parse(readFileSync(profilePath, "utf8"))
  : null;
if (profile) {
  const qc = profile.constraints.question_count;
  const rc = profile.constraints.result_count;
  if (brief.question_count < qc.min || brief.question_count > qc.max)
    FAIL(`custom-lite profile 要求 question_count ${qc.min}–${qc.max}，brief 为 ${brief.question_count}。`);
  if (brief.result_count < rc.min || brief.result_count > rc.max)
    FAIL(`custom-lite profile 要求 result_count ${rc.min}–${rc.max}，brief 为 ${brief.result_count}。`);
  if (brief.image_required)
    warnings.push("custom-lite 默认不做全套独立 AI 插画；brief.image_required=true 属于围栏外升级，需在 notes 里写明升级依据。");
}

// 4) 其他语义提醒（不阻断）
if (commercial_mode === "internal" && brief.owner_id !== "internal")
  warnings.push("commercial_mode=internal 但 owner_id 不是 internal——确认归属是否正确。");
if (commercial_mode === "hosted_creator" && !brief.created_for)
  warnings.push("hosted_creator 模式建议填写 created_for（客户/创作者标识）。");
if (commercial_mode === "hosted_creator" && brief.revenue_share_hint)
  warnings.push("revenue_share_hint 仅为记录意图；当前没有分账基础设施，不构成任何承诺。");
if (brief.status && brief.status !== "draft")
  warnings.push(`新建工作目录的 brief.status 应为 draft（当前 ${brief.status}）。`);

/* ------------------------------------------------------------- file writers */
const pad = (i) => String(i + 1).padStart(2, "0");
const now = new Date().toISOString().slice(0, 10);
const skillFor =
  commercial_mode === "skill_generated"
    ? "factory/skills/SELLABLE_TEST_CREATOR.md"
    : "factory/skills/INTERNAL_TEST_FACTORY.md";

const resultSlot = (i) => ({
  id: `TODO_result_${pad(i)}`,
  name: null, subtitle: null, keywords: null, core_energy: null,
  inner_conflict: null, relationship_style: null, strengths: null,
  blind_spots: null, reading: null,
  back_subtitle: null, back_reading: null,
  share_line: null, visual_direction: null, character_basis: null, mythic_trace: null,
});
const questionSlot = (i) => ({
  id: `TODO_q${pad(i)}`,
  question: null,
  options: [{ text: null, scores: {} }, { text: null, scores: {} }, { text: null, scores: {} }],
  dimension: null,
  editor_note: null,
});

const files = {};

files["brief.json"] = JSON.stringify(
  { ...brief, status: "draft", _created: now, _created_by: "factory/create-test.mjs", _schema: "factory/brief.schema.json" },
  null, 2
) + "\n";

files["STATUS.md"] = `# STATUS — ${brief.title}（${product_id}）

- commercial_mode: \`${commercial_mode}\` · owner_id: \`${brief.owner_id}\` · language: \`${brief.language}\`
- brief: ${briefArg} → 本目录 \`brief.json\`（${now} 由 create-test 生成）
- 规格锁定：${brief.question_count} 题 / ${brief.result_count} 结果 / ${brief.result_style} / 插画 ${brief.image_required ? "需要" : "不需要（预设视觉）"}
${profile ? "- profile: **custom-lite**（factory/profiles/custom-lite.json 围栏内生产）" : ""}

## 阶段状态

| 阶段 | 文件 | 状态 |
|---|---|---|
| S1 结果设计 | result_design.md | TODO |
| S2 内容 | questions.json + scoring_spec.md + copy.md | TODO |
| S3 视觉 | visual_spec.md${brief.image_required ? " + image_prompts.md" : "（预设视觉，无独立插画）"} | TODO |
| S4 QA | qa_report.md | TODO |
| S5 发布 | publish_checklist.md | TODO（上线时执行） |

## 下一步（给继续的 agent 的协议）

1. 先读 \`${skillFor}\`，再读对应阶段 SOP（factory/STAGE_*.md）。
2. 按 S1→S5 顺序填本目录文件；只填 TODO / null 处，**不假造任何已完成内容**。
3. 每完成一个文件：把上表状态改 DONE，并在文件末尾写一行证据（跑过的校验命令/评审记录）。
4. 遇到与 brief 冲突的事实，停下来写进 qa_report.md 的"冲突记录"，不要自行改 brief。

## 边界（本产品适用）

${commercial_mode === "skill_generated"
  ? "- skill_generated：本产品**不在本仓库部署**；产出物按 SELLABLE skill 的交付包规范整理。\n- 不得引用本仓库私有服务器/部署/许可设施。"
  : profile
    ? "- custom-lite 围栏：预设布局、预设视觉、共享域名、无商业托管权、无独立后端（见 factory/CUSTOM_LITE.md）。"
    : "- 走本仓库全流水线：S4 注册 server/content/products/ + deploy；遵守十条铁律（factory/README.md §四）。"}
`;

files["result_design.md"] = `# S1 结果设计 — ${brief.title}（${brief.result_count} 个原型）

> 目标：过 STAGE_1 的 G1 剩余项 + 完成原型区分表。依据 brief：${brief.audience}
> 语调约束：${brief.tone.join(" / ")}

## 1. 原型区分表（每行必填，两两区分）

| # | 结果 id（slug，永不变） | 名称 | 核心能量 core_energy | 内在冲突 inner_conflict | 与相邻原型的区分（一句） |
|---|---|---|---|---|---|
${Array.from({ length: brief.result_count }, (_, i) => `| ${i + 1} | ${TODO} | ${TODO} | ${TODO} | ${TODO} | ${TODO} |`).join("\n")}

## 2. 维度覆盖清单（每题落的维度；同一心理问题不许换皮重问）

友谊 / 亲密吸引 / 家庭期待 / 隐私边界 / 孤独与恢复 / 野心与妥协 /
尊严与尴尬 / 嫉妒与羡慕 / 变化与不确定 / 归属与独立 / 被误解 / 隐秘愿望

## 3. 红线（照抄自 CONTENT_EDITOR_PROMPT.md，不可协商）

- 不诊断、不贴标签、不羞辱、不声称科学有效性；
- 没有哪个选项明显更聪明/更善良/更成熟；
- 每个结果都要"有吸引力也有张力"：没有完美结果，也没有侮辱性结果；
- 结果 id 用稳定 slug，永不用显示名做路由键。

## 4. 自检（过门条件）

- [ ] ${brief.result_count} 个原型两两区分成立（写满区分列）
- [ ] 每个原型的冲突结构能支撑 ≥2 道不同维度的题
- [ ] 与 brief.notes 声明的差异化一致

> 证据：____（完成人/日期/评审一句话）
`;

files["questions.json"] = JSON.stringify(
  {
    schema_version: "content-upgrade-1",
    status: "draft",
    _how_to_fill: [
      "本文件是题库骨架：所有 null / TODO 处待填，禁止假造终稿。",
      "规程：factory/STAGE_2_CONTENT.md + 仓库根 CONTENT_EDITOR_PROMPT.md（编辑五轴自检 <20 分重写）。",
      `题量 ${brief.question_count}、每题恰好 3 个选项；scores 只允许出现 result_design.md 已定的结果 id，权重 0–3 整数（3 主线索 / 1 次线索）。",
      "结果对象含双面卡字段（back_subtitle/back_reading），单面卡系列留 null 即可。",
      "完成后跑 scoring_spec.md 里的校验命令，再删除 _how_to_fill 与各 TODO 标记，status 改 review。",
      `语调约束（来自 brief.tone）: ${brief.tone.join("；")}`,
    ],
    collection_title: brief.title,
    editorial_summary: {
      audience: brief.audience,
      tone: brief.tone,
      design_principles: [],
      changes_from_prototype: ["全新生产，无原型；design_principles 在自检通过后回填"],
    },
    themes: [
      {
        id: brief.theme,
        title: null,
        subtitle: null,
        disclaimer: "This is a cultural character-style experience, not a scientific personality assessment.",
        results: Array.from({ length: brief.result_count }, (_, i) => resultSlot(i)),
        questions: Array.from({ length: brief.question_count }, (_, i) => questionSlot(i)),
        scoring: { method: null, normalization_bounds: null, tie_break: null, result_order: null },
        editorial_review: null,
      },
    ],
  },
  null, 2
) + "\n";

files["scoring_spec.md"] = `# S2 评分规格 — ${product_id}

> 真实评分数据（scores/权重/边界）随 questions.json 提交；本文件定**规格**并记录校验证据。

## 标准评分模型（与线上产品同构，偏离需说明理由）

- 每个选项的 scores 为 0–3 整数：3=主线索，1=次线索；只计最终结果 id，不给中间维度记分；
- 归一化：\`100 × (累计分 − min) / (max − min)\`（range_normalized_sum）；
- 平局依次比：未取整归一化分 → 3 分选项占比 → scoring.result_order；
- **每个结果可达**（专属倾向机器人可获胜），且无支配结果（随机作答份额极差收敛）。

## TODO

- [ ] 确定各结果权重结构后回填 questions.json 的 scoring 字段（method/normalization_bounds/tie_break/result_order）
- [ ] 校验三件套（复制/参数化 greek 的脚本）：
      \`python tools/rebalance_*_scoring.py --check\`
      \`python tools/simulate_*_scoring.py\`
      \`python tools/audit_encoding.py\`
- [ ] 记录：随机作答分布摘要 + 每个结果 ≥1 条精确获胜路径

> 证据：____（命令输出摘要/日期）
`;

files["copy.md"] = `# S2 文案任务 — ${brief.title}

> 语言: ${brief.language}。语调: ${brief.tone.join(" / ")}。本文件承载结果正文的编辑任务，终稿写回 questions.json 对应结果对象。

## 每个结果需要（${brief.result_count} 个，逐一完成）

| 字段 | 要求 |
|---|---|
| name / subtitle | 显示名 + 一句副题；不泄露结果 id |
| keywords | 3–5 个可分享的词 |
| core_energy / inner_conflict | 内部字段：能量与张力（对应 result_design.md） |
| relationship_style / strengths / blind_spots | 长处与盲点成对出现，无完美结果 |
| reading | 结果正文：有吸引也有张力的文学肖像；不诊断、不预测爱情/职业/人生 |
| share_line | 一句可截图传播的话（不制造人格权威感） |
| visual_direction | 给 S3 的一句话画面指令（若 image_required=true 必填） |
| character_basis / mythic_trace | 素材边界声明 / 系列彩蛋（如有） |

## 免责声明（固定，不改写）

This is a cultural character-style experience, not a scientific personality assessment.

## 自检

- [ ] ${brief.result_count} 个结果正文完成并写回 questions.json
- [ ] 五轴自检全部 ≥20 分（场景具体性/情绪共鸣/选项平衡/结果区分/语言新鲜度）
- [ ] 无抄袭、无诊断声称、无对用户的性别/婚恋/经济状况作断言

> 证据：____
`;

files["visual_spec.md"] = brief.image_required
  ? `# S3 视觉系统 — ${brief.title}

> 视觉方向（brief）：${brief.visual_direction}
> 正典方法论：v2/VISUAL_SYSTEM_V2.md。本文件是**本系列自己的**视觉系统文档，先于任何生成完成。

## 1. 系列概念与北极星

- 一句话（用户刷到分享图时为什么停下）：${TODO}

## 2. 固定语法（系列不变量 6–7 条：幅面/色族/线条/平涂/无文字/风格语言/正背关系）

- 幅面：4:5 竖幅（沿用系列惯例）
