#!/usr/bin/env node
// create-test.mjs — Test Factory 开工命令。
//
// 用法：
//   node factory/create-test.mjs <brief.json>
//   node factory/create-test.mjs factory/examples/example-brief.json
//
// 职责（有意保持最小）：
//   1. 按 factory/brief.schema.json 校验 brief（内置 draft-07 子集校验器，零依赖）
//   2. 附加语义校验：product_id 唯一性 / 防覆盖 / custom-lite profile 硬约束
//   3. 创建标准工作目录 factory/work/<product_id>/，写入各阶段任务文件骨架
//   4. 打印下一步操作说明，交给后续 agent 按固定协议继续生产
//
// 不调用模型 API，不生成任何内容；未完成处一律写 TODO / null，不假造结果。

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const FACTORY = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(FACTORY, "..");
const WORK_DIR = join(FACTORY, "work");
const PRODUCTS_DIR = join(REPO, "server", "content", "products");

const FAIL = (msg) => {
  console.error(`✗ ${msg}`);
  process.exit(1);
};
const TODO = "TODO（未完成，禁止假造；完成后删除此标记并填写依据）";

/* ---------------------------------------------------------------- validator */
// 支持 draft-07 子集：type(含数组)/required/properties/additionalProperties/
// enum/pattern/minLength/maxLength/minimum/maximum/items/minItems/maxItems
function matchType(t, v) {
  switch (t) {
    case "string": return typeof v === "string";
    case "integer": return Number.isInteger(v);
    case "number": return typeof v === "number" && Number.isFinite(v);
    case "boolean": return typeof v === "boolean";
    case "array": return Array.isArray(v);
    case "object": return v !== null && typeof v === "object" && !Array.isArray(v);
    case "null": return v === null;
    default: return false;
  }
}
function describe(v) {
  if (v === null) return "null";
  if (Array.isArray(v)) return "array";
  return typeof v;
}
function validateNode(schema, value, path, errs) {
  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
  if (types.length && !types.some((t) => matchType(t, value))) {
    errs.push(`${path}: 期望类型 ${types.join("|")}，实际 ${describe(value)}`);
    return;
  }
  if (schema.enum && !schema.enum.includes(value)) {
    errs.push(`${path}: 必须是 ${schema.enum.join(" / ")}，实际 ${JSON.stringify(value)}`);
  }
  if (typeof value === "string") {
    if (schema.minLength != null && value.length < schema.minLength)
      errs.push(`${path}: 长度 ${value.length} < minLength ${schema.minLength}`);
    if (schema.maxLength != null && value.length > schema.maxLength)
      errs.push(`${path}: 长度 ${value.length} > maxLength ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value))
      errs.push(`${path}: "${value}" 不匹配 /${schema.pattern}/`);
  }
  if (typeof value === "number") {
    if (schema.minimum != null && value < schema.minimum)
      errs.push(`${path}: ${value} < minimum ${schema.minimum}`);
    if (schema.maximum != null && value > schema.maximum)
      errs.push(`${path}: ${value} > maximum ${schema.maximum}`);
  }
  if (Array.isArray(value)) {
    if (schema.minItems != null && value.length < schema.minItems)
      errs.push(`${path}: ${value.length} 项 < minItems ${schema.minItems}`);
    if (schema.maxItems != null && value.length > schema.maxItems)
      errs.push(`${path}: ${value.length} 项 > maxItems ${schema.maxItems}`);
    if (schema.items) value.forEach((v, i) => validateNode(schema.items, v, `${path}[${i}]`, errs));
  }
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    for (const req of schema.required ?? []) {
      if (!(req in value)) errs.push(`${path}: 缺少必填字段 "${req}"`);
    }
    for (const [k, v] of Object.entries(value)) {
      const ps = schema.properties?.[k];
      if (ps) validateNode(ps, v, `${path}.${k}`, errs);
      else if (schema.additionalProperties === false)
        errs.push(`${path}: 未知字段 "${k}"（schema additionalProperties=false）`);
    }
  }
}
const validateBrief = (schema, brief) => {
  const errs = [];
  validateNode(schema, brief, "brief", errs);
  return errs;
};

/* ------------------------------------------------------------- load & check */
const [briefArg] = process.argv.slice(2);
if (!briefArg) {
  console.log("用法: node factory/create-test.mjs <brief.json>");
  console.log("示例: node factory/create-test.mjs factory/examples/example-brief.json");
  process.exit(1);
}
const briefPath = resolve(briefArg);
if (!existsSync(briefPath)) FAIL(`brief 文件不存在: ${briefPath}`);

let brief;
try {
  brief = JSON.parse(readFileSync(briefPath, "utf8"));
} catch (e) {
  FAIL(`brief 不是合法 JSON: ${e.message}`);
}
const schema = JSON.parse(readFileSync(join(FACTORY, "brief.schema.json"), "utf8"));
const errors = validateBrief(schema, brief);
if (errors.length) {
  console.error(`✗ brief 未通过 schema 校验（${errors.length} 项）：`);
  for (const e of errors) console.error(`  - ${e}`);
  process.exit(1);
}

const { product_id, commercial_mode } = brief;
const warnings = [];

// 1) product_id 不得与在售产品目录冲突（绝不覆盖已有产品）
const RESERVED = new Set(["work", "examples", "profiles", "skills", "creators", "templates"]);
if (RESERVED.has(product_id)) FAIL(`product_id "${product_id}" 是工厂保留名，请更换。`);
if (existsSync(PRODUCTS_DIR)) {
  const clash = readdirSync(PRODUCTS_DIR).find(
    (d) => d.toLowerCase() === product_id.toLowerCase()
  );
  if (clash) FAIL(`product_id "${product_id}" 与在售产品目录 server/content/products/${clash} 冲突。不允许覆盖已有产品，请更换 ID。`);
}

// 2) 防覆盖：工作目录已存在则拒绝
const workDir = join(WORK_DIR, product_id);
if (existsSync(workDir)) {
  FAIL(`工作目录已存在: factory/work/${product_id}（防覆盖，不重跑。如需重开请手动归档旧目录后改名）`);
}

// 3) custom-lite profile：custom_private 模式下硬约束
const profilePath = join(FACTORY, "profiles", "custom-lite.json");
const profile = commercial_mode === "custom_private" && existsSync(profilePath)
  ? JSON.parse(readFileSync(profilePath, "utf8"))
  : null;
